import json,sys
d=json.load(sys.stdin)
def walk(x,depth=0):
    if isinstance(x,dict):
        i=x.get('id','')
        if 'picrep' in str(i):
            print(json.dumps({k:v for k,v in x.items() if k in ('id','status','summary','task_refs','decls')},indent=1)[:1500])
        for v in x.values(): walk(v,depth+1)
    elif isinstance(x,list):
        for v in x: walk(v,depth)
walk(d)
