    f^*\bigl(\mathcal{F} \otimes_{\mathcal{O}_X} L^{\otimes m}\bigr)
    \;\cong\;
    f^*\mathcal{F} \otimes_{\mathcal{O}_Y} \bigl(f^*L\bigr)^{\otimes m}.
  \]
